using ICommand = AspNetCore.Simple.Sdk.Mediator.ICommand;

namespace AspNetCore.MinimalApi.Sdk.CodeRules
{
    [TestCategory("Coding-Rules")]
    [TestCategory("Mediator")]
    [TestClass]
    public class RJIT_CR_M_00002 : MediatorTestBase
    {
        private string[] MediatorRequestTypes = new string[] { "IRequest", "IQuery", "ICommand" };

        // 1. Handler and commands and queries have to be in the same file
        // 2. Command/Queries have to use the Response type as generic parameter
        // 3. MediatR registration have to be done for each assembly in which a handler is declared.
        [TestMethod]
        public void Query_Or_Commands_Class_Must_Have_A_Handler_Implementation()
        {
            var requestClasses = (from @class in Classes
                                  from baseType in @class.BaseTypes
                                  where MediatorRequestTypes.Any(type => baseType.TypeName.StartsWith(type))
                                  select @class).Distinct().ToImmutableList();

            var exitsingHandlers = (from implementation in MediatorImplementations
                                    where requestClasses.Any(request => request.Name == implementation.Handler.Name)
                                    select implementation).ToImmutableList();

            var missingHandlers = requestClasses.Except(exitsingHandlers, item => item.Name, item => item.Handler.Name).ToList();

            var missingHandlerErrorInfo = (from missingHandler in missingHandlers
                                           select new
                                           {
                                               Error = $@"
No MediatR handler was found for the request: '{missingHandler.Name}'.
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
Request Type:    {missingHandler.Name}
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
Sample:          

{missingHandler.BuildMediatorImplementation()}
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
"
                                           }).ToImmutableList();

            Assert.IsTrue(missingHandlerErrorInfo.IsEmpty(),
                @$"
Documentation: {DocumentationDomain}#RJIT_CR_MR_00002

Query/Command handler is not in the same file as the processing part. 
For debug and maintainability aspects put the query or command into your handler
in which the processing take place. It is called F12 debug experience:{Environment.NewLine}{missingHandlerErrorInfo.Select(e => e.Error).Flatten(Environment.NewLine)}");
        }
    }

    public static class ClassDeclarationExtensionsNew
    {
        private static string[] MediatorRequestTypes = new string[] { "IRequest", "IQuery", "ICommand" };

        private static Regex genericTypeRegex = new Regex(@"<(.*)>");

        public static string BuildMediatorImplementation(this Class source)
        {
            var mediatorRequestType = source.BaseTypes.FirstOrDefault(b => MediatorRequestTypes.Contains(b.TypeName));
            if (mediatorRequestType.IsNull())
            {
                throw new ArgumentException("It is not possible to create a Mediator handler for the requested class, because it doed not implement an required interface to be a Mediator request.");
            }

            var stringBuilder = new StringBuilder();

            // Now we have to check for generic types, if we have a generic type then it is a query or command with response type
            if (mediatorRequestType.TypeName.Contains("<"))
            {
                var responseType = genericTypeRegex.Match(mediatorRequestType.TypeName).Groups[0].Value;

                stringBuilder.AppendLine(source.SyntaxTree.FormatSyntaxTree());
                stringBuilder.AppendLine($"internal sealed class {source.Name}Handler : ICommandHandler<{source.Name}>");
                stringBuilder.AppendLine("{");
                stringBuilder.AppendLine($"public Task<{responseType}> Handle({source.Name} request, CancellationToken cancellationToken)");
                stringBuilder.AppendLine("{");
                stringBuilder.AppendLine("throw new NotImplementedException();");
                stringBuilder.AppendLine("}");
                stringBuilder.AppendLine("}");

            }
            else
            {
                stringBuilder.AppendLine(source.SyntaxTree.FormatSyntaxTree());
                stringBuilder.AppendLine($"internal sealed class {source.Name}Handler : ICommandHandler");
                stringBuilder.AppendLine("{");
                stringBuilder.AppendLine($"public Task Handle({source.Name} request, CancellationToken cancellationToken)");
                stringBuilder.AppendLine("{");
                stringBuilder.AppendLine("throw new NotImplementedException();");
                stringBuilder.AppendLine("}");
                stringBuilder.AppendLine("}");
            }

            var formattedCode = stringBuilder.ToString().FormatSyntaxTree();
            return formattedCode;
        }
    }
